function extraDiagram(kind){const t=(x,y,s)=>'<text x="'+x+'" y="'+y+'">'+esc(s)+'</text>';let body='';
 if(kind==='frames')body='<path d="M70 220H590 M80 220V50 M250 170H540 M260 170V75"/>'+t(88,52,'S: laboratory')+t(270,75,'S′: spacecraft')+t(290,140,'u′ measured here')+t(420,250,'v: frame motion →');
 if(kind==='slits')body='<path d="M200 40V125 M200 145V190 M200 210V290 M560 40V290 M205 135L560 165 M205 200L560 165"/>'+t(120,28,'two slits')+t(560,320,'screen')+t(320,100,'path 1')+t(320,245,'path 2')+t(40,172,'d')+t(335,310,'screen distance L');
 if(kind==='polarisation')body='<path d="M60 160H610 M190 50V270 M390 50V270 M390 90H470"/>'+t(125,35,'first axis ↑')+t(325,300,'second axis →')+t(70,130,'light →')+t(490,205,'crossed axes');
 if(kind==='spectrum')body='<path d="M80 260H620 M80 260V40 M90 255Q180 200 235 150Q300 100 600 248 M90 250Q150 30 215 55Q280 80 600 220"/>'+t(290,35,'hotter: higher, left-shifted peak')+t(420,290,'wavelength λ →')+t(95,90,'intensity');
 if(kind==='photoelectric')body='<path d="M90 230H610 M90 230V40 M180 260L550 65"/>'+t(100,35,'stopping potential Vs')+t(430,270,'frequency f')+t(300,115,'slope h/e')+t(130,290,'threshold intercept');
 if(kind==='levels'||kind==='laser'||kind==='led')body='<path d="M120 65H520 M120 145H520 M120 245H520 M310 80V230 M310 230L300 210 M310 230L320 210"/>'+t(535,70,'higher state')+t(535,250,'lower state')+t(330,195,'photon: E = ΔE')+(kind==='laser'?t(125,120,'stimulating photon →'):kind==='led'?t(125,120,'electrical carrier excitation'):t(125,120,'possible intermediate state'));
 if(kind==='xray')body='<path d="M70 150H430 M430 50V260 M430 150L600 75 M430 150L600 220"/>'+t(80,120,'accelerated electrons →')+t(330,285,'target')+t(500,45,'X-ray photons')+t(80,225,'kinetic energy ≤ eV');
 if(kind==='photovoltaic')body='<rect x="230" y="65" width="190" height="200"/><path d="M60 100L230 130 M60 160L230 185 M420 105H570V225H420"/>'+t(65,70,'incident photons')+t(250,145,'semiconductor')+t(460,170,'external load')+t(215,300,'carrier separation at junction');
 return '<svg class="pf-svg" viewBox="0 0 760 340" role="img" aria-label="'+esc(kind+' model schematic')+'"><g fill="none" stroke="#174d75" stroke-width="3">'+body.replace(/<text[\s\S]*?<\/text>/g,'')+'</g><g font-family="Arial,sans-serif" font-size="18" fill="#12374f">'+(body.match(/<text[\s\S]*?<\/text>/g)||[]).join('')+'</g></svg><p class="pf-caption">Concept schematic, not to scale. Use the stated question values for calculations.</p>'}
for(const e of data.extras){const p=parents[e.parent];if(!p)throw Error('Missing extra parent '+e.parent);const spec={question:e.exam.q,points:e.exam.points,claim:e.claim};const bank=claimBank(spec);const ss=[screen('Lesson focus and retrieval','<h2>'+esc(e.title)+'</h2><p>Additional focused Year 12 lesson · approximately 40–50 minutes.</p><p class="pf-prerequisite">Retrieve: '+esc(p.topic.title)+'. Write the key quantities and their units before starting.</p>'),screen('Do Now · identify the misconception',checks([bank[0]],e.id+'-now'),'interactive'),...e.theory.map((t,i)=>screen('I · '+['physical mechanism','relationship and interpretation','conditions and applications'][i],phase('I')+text(t))),screen('I · diagram and representation',phase('I')+extraDiagram(e.diagram)),screen('I · fully modelled example',phase('I')+'<div class="pf-model"><p>'+esc(e.model.q)+'</p><ol>'+e.model.steps.map(s=>'<li>'+colour(s)+'</li>').join('')+'</ol></div>','worked'),screen('We · guided worked example',phase('WE')+guided(e.guided),'practice'),screen('We · diagnose the misconception',phase('WE')+'<p>Explain this claim before comparing: '+esc(e.claim)+'</p>'+checks(bank,e.id+'-we'),'interactive'),screen('You · independent exam-style question',exam(spec,e.id),'practice'),screen('You · exit ticket',phase('YOU')+'<p>Connect the mechanism to one observable result. Name one assumption in the model and one unit or diagram detail that matters.</p>'+checks(bank,e.id+'-exit'),'interactive')];const entry={id:e.id,parentTopic:e.parent,title:e.title,icon:p.topic.icon,subtitle:'Additional focus · '+ss.length+' screens · two worked applications · written marking table'};window['Year'+p.year+'PhysicsLessons'][e.id]={title:e.title,parentTopic:e.parent,screens:ss,bank,wire:r=>wire(r),focus:spec,theory:e.theory.join(' ')};const group=sequences[p.year][p.unit].find(g=>g.parent.id===e.parent);group.lessons.push(entry);newLessons.push({year:p.year,unit:p.unit,...entry})}
function url(t,topic){return 'topic-hub.html?'+new URLSearchParams({course:'Physics ATAR',year:t.year,unit:t.unit,topic:topic||t.id})}
function printLesson(id,withKey=false){const e=newLessons.find(x=>x.id===id);const m=e&&window['Year'+e.year+'PhysicsLessons'][id];if(!m)return '';const spec=m.focus;const illustration=m.screens.map(s=>s.html.match(/<svg\b[\s\S]*?<\/svg>/i)?.[0]).find(Boolean)||'';return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'+esc(m.title)+'</title><style>body{font:12pt/1.6 Arial;margin:20mm}h1{font-size:20pt}table{border-collapse:collapse;width:100%}td,th{border:1px solid #777;padding:8px}.pf-print-space{height:220px;background:repeating-linear-gradient(white,white 27px,#aaa 28px)}svg{max-width:100%;max-height:250px}button,input,textarea{display:none}details{display:block}h2{break-after:avoid}table,svg{break-inside:avoid}</style></head><body><h1>'+esc(m.title)+'</h1><p>Physics ATAR · Year '+e.year+' · '+esc(e.unit)+'</p><p>Name: __________________________ Date: __________</p><h2>Key explanation</h2><p>'+esc(m.theory)+'</p>'+illustration+'<p>Illustrative model, not to scale. Use the question values.</p><h2>Independent question · 3 marks</h2><p>'+esc(spec.question)+'</p><div class="pf-print-space"></div><h2>Explain and reflect</h2><p>Correct this claim: '+esc(spec.claim)+'</p><div class="pf-print-space"></div>'+(withKey?'<h2>Suggested marking table</h2>'+marking(spec.points):'')+'<p>Written work needs self-review or teacher marking.</p></body></html>'}
function mountTools(topic,host){const entry=newLessons.find(e=>e.id===topic.id);if(!entry)return;const tools=document.createElement('div');tools.className='pf-tools';tools.innerHTML='<a href="'+esc(url(entry,entry.parentTopic))+'">Full original topic reference</a><button class="btn dark" data-pf-print>Print worksheet</button><button class="btn dark" data-pf-print-key>Print worksheet + suggested key</button>';host.prepend(tools);for(const [selector,key] of [['[data-pf-print]',false],['[data-pf-print-key]',true]])tools.querySelector(selector).onclick=()=>{const w=window.open('','_blank');if(!w){const p=document.createElement('p');p.textContent='Allow pop-ups to open the printable worksheet.';tools.append(p);return}w.document.open();w.document.write(printLesson(topic.id,key));w.document.close();w.focus();w.print()}}
for(const year of [11,12]){const player=window['Year'+year+'PhysicsPlayer'];if(!player)throw Error('Missing Physics player '+year);const old=player.build;player.build=(topic,host)=>{old(topic,host);mountTools(topic,host)}}
function render(host,year,unit,open){const groups=sequences[year][unit]||[];window.vaultVisibleLessonTopics=groups.flatMap(g=>[...g.lessons,g.parent].map(t=>({topic:t,open:()=>open(t)})));host.innerHTML='<div class="topic-head"><h2>'+esc(unit)+'</h2><p>'+groups.reduce((n,g)=>n+g.lessons.length,0)+' focused lessons. Work through each sequence in order. The original complete topic is available as a reference.</p></div>'+groups.map((g,i)=>'<section class="physics-sequence"><span class="eyebrow">SEQUENCE '+String(i+1).padStart(2,'0')+'</span><h3>'+esc(g.parent.title)+'</h3><div class="topic-tile-grid">'+g.lessons.map((t,j)=>'<button class="topic-tile" data-pf-topic="'+esc(t.id)+'"><span class="topic-number">LESSON '+(j+1)+'</span><strong>'+esc(t.title)+'</strong><small>'+esc(t.subtitle)+'</small><span class="topic-open">Start lesson →</span></button>').join('')+'</div><details class="physics-reference"><summary>Original complete topic reference and existing standalone task</summary><p>Use the complete original module for consolidation or an existing assignment. New lessons above have their own focused practice.</p><button class="btn dark" data-pf-topic="'+esc(g.parent.id)+'">Open full topic reference</button></details></section>').join('');host.querySelectorAll('[data-pf-topic]').forEach(b=>b.onclick=()=>window.vaultVisibleLessonTopics.find(x=>x.topic.id===b.dataset.pfTopic)?.open())}
window.PhysicsFocused={sequences,lessons:newLessons,parents,render,printLesson,setAccount(uid){accountUid=String(uid||'')}};
