window.PhysicsExplicitGuides=G;
const extraGuides={
 'relativistic-velocity-addition':['Relative velocity: speed and direction in a stated frame; u′: probe velocity in spacecraft frame; v: spacecraft velocity in laboratory; u: probe velocity in laboratory','u = (u′ + v)/(1 + u′v/c²)','Label laboratory S and spacecraft S′. Label both velocity signs; a backward ejection in S′ can still move forward in S.'],
 'young-double-slit':['Coherent sources: stable phase relationship; d: slit separation; L: screen distance; x: fringe position; Path difference: difference in ray lengths','d sinθ = nλ; small-angle fringe spacing Δx = λL/d','Label two slits, slit separation d, screen distance L, central maximum and x along the screen. Path difference is between the two rays, not their average length.'],
 'light-polarisation':['Transmission axis: allowed electric-field direction; Unpolarised: no fixed transverse orientation; θ: angle between successive polariser axes; Intensity: power per area','Iafter first ideal polariser = Iunpolarised/2; Iafter analyser = Iincident cos²θ','Label propagation separately from electric-field oscillation and polariser axes. θ is between the axes, not between a ray and a sheet.'],
 'black-body-radiation':['Black body: ideal absorber and thermal emitter; λpeak: wavelength of maximum spectral intensity; Absolute temperature: temperature in K; Emissivity: real-surface emission fraction','λpeak T = 2.90 × 10⁻³ m K; P = σAT⁴ for an ideal black body','Label wavelength and spectral intensity axes. Mark each peak and its temperature; a hotter curve peaks at a shorter wavelength.'],
 'photoelectric-planck-investigation':['Stopping potential Vs: voltage stopping the fastest electrons; Threshold frequency f0: minimum extraction frequency; Work function φ: extraction energy; Gradient: rise in Vs divided by rise in f','eVs = hf − φ; slope of Vs against f = h/e; f0 = φ/h','Label voltage in V and frequency in Hz, the straight-line gradient and the frequency-axis intercept. The voltage-axis intercept is negative in the extrapolated ideal line.'],
 'fluorescence-phosphorescence':['Excitation: absorption raising an energy state; Non-radiative transfer: energy given to other degrees of freedom; Fluorescence: prompt emission; Phosphorescence: delayed emission','Eabsorbed = Ephoton emitted + Eother transfers; Ephoton = hc/λ','Label absorption upward, any non-radiative transition and emission downward. The emitted photon need not carry all the absorbed energy.'],
 'x-ray-production':['Bremsstrahlung: radiation from electron deceleration; Characteristic line: photon from a discrete atomic transition; Tube voltage: electron accelerating potential; Cutoff: minimum possible wavelength','Emax = eV; λmin = hc/(eV)','Label accelerating voltage, incoming electrons, target and outgoing photons. Distinguish the continuous background, discrete lines and short-wavelength cutoff.'],
 'laser-stimulated-emission':['Stimulated emission: triggered matching photon emission; Population inversion: more particles in upper relevant state; Pump: energy source; Cavity: optical feedback system','Ephoton = ΔE = hf = hc/λ','Label pump, upper and lower states, incoming trigger photon and matching emitted photon. Show both mirrors and identify the partly transmitting output mirror.'],
 'photovoltaic-cells':['Irradiance: incident radiant power per area; Carrier: mobile electron or hole; Junction field: separates carriers; Efficiency: useful electrical output divided by incident radiant input','Pin = irradiance × area; Pout = VI; η = Pout/Pin','Label incident photons, junction, separated carriers, external load and conventional current. The energy input is light; the field separates charges rather than supplying unlimited energy.'],
 'led-quantum-emission':['Recombination: electron and hole transition; Energy gap: relevant state separation; Forward voltage: diode operating drop; Series resistor: current limiter','λ = hc/Ephoton; Rseries = (Vsupply − Vforward)/I','Label diode polarity, series resistor and supply. Distinguish photon energy from the total supply voltage; the resistor takes the remaining voltage.']
};
