for(const id of ['relativity-foundations','relativity-effects','relativity-energy','particle-physics','relativistic-velocity-addition'])if(!G[id].relations.some(r=>r.startsWith('γ =')))G[id].relations.unshift('γ = 1/√(1 − (v/c)²)');
const lawReasons=[
 [/ΔT|mc(?=Δ)|latent|mL\b/,'The equation distinguishes a temperature change from a phase change. A temperature interval is final minus initial; 1 K and 1 °C are equal intervals. Keep masses in kg when c and L are given per kg.'],
 [/γ|Lorentz|relativ|u′/,'γ is dimensionless and depends on v/c, not on a speed entered in km h⁻¹. Compute 1 − (v/c)² inside brackets before taking the square root. Identify the frame and proper quantity before multiplying or dividing by γ.'],
 [/τ|torque|sin.*θ|cos.*θ/,'An angle must be identified geometrically before using sine or cosine. A perpendicular projection determines which component enters the equation. Set the calculator to degrees when the stated angle uses °.'],
 [/GM|grav|r²|orbit/,'The gravitational distance is measured from the central mass, so convert altitude to r = R + h where required. Squaring a doubled distance gives a factor of four; apply the power to the complete value.'],
 [/hf|hc|photon|eV/,'Keep energy units consistent. If h is in J s, energy must be in joules and wavelength in metres. A larger photon energy gives a higher frequency and a shorter wavelength because light speed is fixed.'],
 [/I²|VI|V²|IR|current|voltage|resist/,'Use the voltage and current for the same component or branch. Convert milliampere values to amperes. A squared current or voltage applies to the entire numerical value, including its power of ten.'],
 [/mv|momentum|impulse|collision/,'Velocity carries a direction sign. Subtract initial momentum from final momentum, keeping brackets around negative values. A rebound therefore adds the magnitudes when the direction reverses.'],
 [/gradient|area|Δy|Δx/,'Use axis units to identify the result: a gradient has vertical units divided by horizontal units, whereas area has their product. Read points from the fitted line or tangent, and retain the sign.'],
 [/½|v²|u²|at|kinetic/,'Square the complete velocity and use brackets around products in denominators. If solving for a speed from a squared speed, take the square root only after evaluating the whole expression. Choose the sign separately if solving for velocity.'],
 [/N0|half|decay|½\)/,'First find the number of elapsed half-lives t/t½. Raise one half to that number, then multiply by the initial population or activity. Correct any background count rate before using the decay model.']
];
function why(text,g){return lawReasons.find(([re])=>re.test(text))?.[1]||g.mechanism;}
function formulaPanel(g){return '<h2>Translate words into a model</h2>'+p(g.mechanism)+table(['Relationship','What to establish before using it'],g.relations.map(r=>[r,g.limits]))+'<p><b>Symbols mean physical quantities:</b> read the quantity and unit together. The same letter can mean something else in another context, so use this lesson’s definitions.</p>';}
function symbolMap(g){
 const wrap=(value,width)=>{const out=[];let line='';for(const word of value.split(/\s+/)){if((line+' '+word).length>width&&line){out.push(line);line=word}else line+=(line?' ':'')+word}if(line)out.push(line);return out};
 const words=(x,y,value,width)=>'<text x="'+x+'" y="'+y+'" fill="#163b50" font-family="Arial,sans-serif" font-size="17">'+wrap(value,width).map((line,i)=>'<tspan x="'+x+'" dy="'+(i?22:0)+'">'+esc(line)+'</tspan>').join('')+'</text>';
 const cards=g.vocabulary.slice(0,4).map(([term,meaning],i)=>{const x=30+(i%2)*370,y=20+Math.floor(i/2)*140;return '<rect x="'+x+'" y="'+y+'" width="345" height="125" rx="10" fill="#edf5fa" stroke="#17658c" stroke-width="2"/>'+words(x+15,y+26,term,32)+words(x+15,y+53,meaning,34)}).join('');
 return '<svg class="pf-svg" viewBox="0 0 760 410" role="img" aria-label="'+esc('Symbols and physical meanings for '+g.relations[0])+'"><title>Read the physical meanings before substituting numbers</title>'+cards+'<path d="M380 288V300" stroke="#17658c" stroke-width="3"/><rect x="30" y="300" width="715" height="100" rx="10" fill="#edf7ef" stroke="#176b53" stroke-width="2"/>'+words(50,330,g.relations.slice(0,2).join('; '),76)+'</svg>';
}
function foundations(id,mod,parent,part){const g=G[id]||G[parent],focus=mod.focus;const title=mod.title;const theory=mod.theory||g.mechanism;
 const statements=theory.split(/(?<=[.!?])\s+(?=[A-Z])/);
 const pieces=[statements.slice(0,2).join(' '),statements.slice(2,4).join(' '),statements.slice(4).join(' ')].filter(Boolean);
 const figure=window.PhysicsFocusedFigure&& !extraGuides[id]?window.PhysicsFocusedFigure(parent,title,part||1):mod.screens.find(s=>/<svg\b/i.test(s.html))?.html.match(/<svg\b[\s\S]*?<\/svg>/i)?.[0]||'';
 return [
 S('Foundation · vocabulary in plain language','<h2>Words you need before starting</h2>'+table(['Word or symbol','Plain-language meaning'],g.vocabulary)),
 S('Foundation · what physically happens','<h2>Picture the process before calculating</h2>'+p(g.mechanism)+p('This lesson develops: '+title)+p(pieces[0]||theory)),
 S('Foundation · choose a relationship',formulaPanel(g)),
 S('Diagram · symbols describe physical quantities','<h2>Decode the symbols and language</h2>'+symbolMap(g)+'<p>The boxes label quantities or concepts used in this topic. The relationship connects these physical meanings; it is not just a string of calculator buttons.</p>'),
 S('Foundation · calculator and algebra decisions','<h2>Understand the operation, not just the answer</h2>'+g.relations.map(r=>'<div class="pf-model"><p><b>'+esc(r)+'</b></p>'+p(why(r,g))+'</div>').join('')),
 S('Foundation · assumptions and limits','<h2>When is this model appropriate?</h2>'+p(g.limits)+p('The physical situation decides whether the relationship is suitable. Check these conditions before choosing numbers.')),
 S('Diagram · identify the physical objects','<h2>Read this labelled model</h2>'+figure+p(g.diagram)),
 S('Diagram · turn labels into reasoning','<h2>What each label tells you</h2>'+p(g.diagram)+p(g.mechanism)+'<p>Follow the labelled directions and compare them with the relationship below. A diagram is a model; its drawn size is not a numerical measurement unless a scale is given.</p>'+table(['Use the diagram to identify','Connect it to'],[['Objects or regions',g.vocabulary[0]?.join(': ')||title],['Direction or change',g.mechanism],['Model condition',g.limits]])),
 S('Diagram · draw and explain it yourself','<h2>Build your own labelled diagram</h2>'+p('On paper, draw the model for '+title+'.')+p(g.diagram)+'<textarea class="pf-response" aria-label="Describe your labelled diagram"></textarea><details><summary>Check the essential features</summary>'+p(g.diagram)+p(g.limits)+'</details>','practice'),
 ...pieces.map((t,i)=>S('Focus · '+['connect cause to effect','distinguish similar ideas','apply the model carefully'][i],'<h2>'+esc(title)+'</h2>'+p(t)+table(['Connect this idea to','Reason'],[['Physical mechanism',g.mechanism],['Applicable condition',g.limits]])+'<details><summary>Check your explanation against the model</summary>'+p(g.mechanism)+'</details>')),
 S('Reasoning · distinguish the misconception','<h2>Find the exact point where the claim fails</h2>'+p(focus?.claim||g.limits)+p(theory)+'<p><b>Write a correction:</b> state the relevant condition, then the physical cause and its consequence. Use the vocabulary precisely.</p><textarea class="pf-response" aria-label="Correct the misconception"></textarea><details><summary>Model correction</summary>'+p(theory)+'</details>','practice'),
 S('Reasoning · connect words, diagram and equation','<h2>One explanation in three representations</h2>'+table(['Representation','What it contributes'],[['In words',g.mechanism],['Labelled diagram',g.diagram],['Relationship',g.relations.join('; ')]])+p(g.limits))
 ];}
// Read each source example into a question and distinct sequential working blocks.
// Full equations and diagrams are retained; this parser never changes source numbers.
function dissect(html){
 const box=document.createElement('div');box.innerHTML=html;
 const root=box.querySelector('.worked-solution,.pf-model')||box;
 const nodes=[...root.children].filter(x=>!/^H[1-6]$/.test(x.tagName)&&!x.classList.contains('pf-phase'));
 const qIndex=nodes.findIndex(n=>n.tagName==='P');if(qIndex<0)return null;
 const question=nodes[qIndex].outerHTML;
 const diagrams=nodes.filter(n=>n.tagName==='svg'||n.tagName==='SVG').map(n=>n.outerHTML).join('');
 const work=nodes.slice(qIndex+1).filter(n=>!['SVG','svg','TEXTAREA'].includes(n.tagName));
 const blocks=[];for(const n of work){if(n.tagName==='OL'||n.tagName==='UL')for(const li of n.children)blocks.push('<p>'+li.innerHTML+'</p>');else if(n.tagName==='DETAILS'){const clone=n.cloneNode(true);clone.querySelector('summary')?.remove();blocks.push(clone.innerHTML)}else blocks.push(n.outerHTML)}
 return {question,diagrams,blocks:blocks.filter(x=>x.replace(/<[^>]+>/g,'').trim())};
}
function numericalGivens(question){
 const plain=question.replace(/<\/?(?:p|div|li|tr|td|th|h[1-6])\b[^>]*>/g,' ').replace(/<[^>]*>/g,'').replace(/&nbsp;/g,' ').replace(/&minus;/g,'−').replace(/&times;/g,'×').replace(/km\s*h\s*[−-]1/g,'km h⁻¹').replace(/m\s*s\s*[−-]1/g,'m s⁻¹').replace(/m\s*s\s*[−-]2/g,'m s⁻²').replace(/10([⁻⁰¹²³⁴⁵⁶⁷⁸⁹]+)/g,(_,n)=>'10'+[...n].map(c=>c==='⁻'?'−':'⁰¹²³⁴⁵⁶⁷⁸⁹'.indexOf(c)).join(''));
 const re=/([+−-]?\d+(?:\.\d+)?(?:\s*[×x]\s*10\s*[−-]?\d+)?)\s*(km h⁻¹|m s⁻¹|m s⁻²|kg|cm²|cm³|mm²|mm³|m²|m³|km|cm|mm|mA|µA|kV|mV|µC|mC|MeV|eV|min|°C|°|K|J|N|V|A|T|Hz|s|m|g|c)(?![A-Za-z])/g;
 const pairs=[];let match;
 while((match=re.exec(plain))){const raw=match[1].replace(/\s/g,''),unit=match[2];let n=Number(raw.replace('−','-'));const sci=raw.match(/^([+−-]?[0-9.]+)[×x]10([−-]?[0-9]+)$/);if(sci)n=Number(sci[1].replace('−','-'))*10**Number(sci[2].replace('−','-'));
  const conversions={'cm²':[1e-4,'m²'],'cm³':[1e-6,'m³'],'mm²':[1e-6,'m²'],'mm³':[1e-9,'m³'],km:[1000,'m'],cm:[0.01,'m'],mm:[0.001,'m'],g:[0.001,'kg'],mA:[0.001,'A'],'µA':[1e-6,'A'],kV:[1000,'V'],mV:[0.001,'V'],'µC':[1e-6,'C'],mC:[0.001,'C'],min:[60,'s'],eV:[1.6e-19,'J'],MeV:[1.6e-13,'J'],'km h⁻¹':[1000/3600,'m s⁻¹'],c:[3e8,'m s⁻¹']};
  const converted=conversions[unit];let message='Use as stated; keep its meaning and any direction sign.';
  if(converted&&Number.isFinite(n))message=raw+' × '+converted[0]+' = '+Number((n*converted[0]).toPrecision(6))+' '+converted[1];
  if(unit==='°')message='Angle in degrees: choose degree mode for sin, cos or tan.';
  if(unit==='°C')message='A temperature is converted to K by adding 273.15; a temperature interval has the same numerical value in K.';
  if(!pairs.some(r=>r[0]===raw+' '+unit))pairs.push([raw+' '+unit,message]);
 }
 return pairs.length?table(['Given value as written','Unit / calculator preparation'],pairs):'';
}
function workedScreens(source,g,label){const d=dissect(source.html);if(!d||!d.blocks.length)return [];
 // Combine prose that introduces an equation with that equation instead of displaying a dangling instruction.
 const chunks=[];let held='';for(const b of d.blocks){const plain=b.replace(/<[^>]+>/g,'').trim();if(/[:：]$/.test(plain)&&!/=/.test(plain)){held+=b;continue;}chunks.push(held+b);held='';}if(held){if(chunks.length)chunks[chunks.length-1]+=held;else chunks.push(held)}
 return [
 S(label+' · understand the question','<h2>'+esc(source.title.replace(/^I · modelled example — /,''))+'</h2>'+d.question+d.diagrams+'<p><b>First read:</b> identify the requested quantity and the start/end events. The diagram and numbers above belong to this example.</p>','worked'),
 ...(numericalGivens(d.question)?[S(label+' · prepare the given values','<h2>Make the numbers usable</h2>'+d.question+numericalGivens(d.question)+'<p>Copy each given beside its symbol on paper. Keep separate values for different objects, stages or frames; equal units do not make two measurements interchangeable.</p>','worked')]:[]),
 S(label+' · choose the method','<h2>Why this method works</h2>'+d.question+p(g.mechanism)+p(g.limits)+table(['Possible relationship','Decision'],g.relations.map(r=>[r,why(r,g)])),'worked'),
 ...chunks.map((b,i)=>S(label+' · step '+(i+1),'<h2>Step '+(i+1)+' of '+chunks.length+'</h2><div class="pf-example-context">'+d.question+'</div><div class="pf-model">'+b+'</div>'+p('Why this step: '+why(b.replace(/<[^>]+>/g,' '),g)), 'worked')),
 S(label+' · interpret and check','<h2>Connect the result back to the situation</h2>'+d.question+chunks.slice(-1).join('')+p(g.limits)+p('Read the final unit and any direction as part of the answer. Compare the result with the physical model: '+g.mechanism),'worked')
 ];}
function caseStudies(g){return [
 S('Application · compare two situations','<h2>Explain what changes and what stays the same</h2>'+p(g.mechanism)+table(['Change to consider','Use this model to explain it'],g.relations.map(r=>[r,g.limits]))+'<p>Give a qualitative prediction first, then check it against the relationship. This is especially useful when a question asks for an explanation rather than a numerical calculation.</p>','practice'),
 S('Application · justify the model boundary','<h2>A plausible claim is not enough</h2>'+p(g.limits)+'<p>Test the explanation by identifying which condition changes when the model stops applying.</p>'+p(g.mechanism)+'<details><summary>What a complete explanation includes</summary>'+p(g.limits)+p(g.diagram)+'</details>','practice')
 ];}
const GRcases=[
 ['A sealed lift with a floating object','An object released inside a freely falling lift floats relative to the lift. Does this show that gravity is absent?','Both lift and object accelerate together under gravity. Their relative acceleration is approximately zero, so the object needs no support force. The local equivalence principle describes this freely falling frame; it does not claim that the surrounding gravitational field disappears. Across a large lift, tidal differences can reveal that the field is not perfectly uniform.'],
 ['Satellite clocks and navigation','A satellite clock is high above Earth and moving rapidly. Explain why one correction is not enough to synchronise it with a ground clock.','Being higher in Earth’s gravitational field makes the satellite clock run faster relative to an otherwise comparable lower clock. Its orbital motion causes special-relativistic time dilation in the chosen Earth frame, contributing in the opposite direction. Navigation accounts for both effects; otherwise timing differences accumulate and become position errors because distance is inferred using light travel time.'],
 ['A distant galaxy seen as multiple images','A massive foreground galaxy lies between Earth and a distant light source. Explain how observers can see several images without several identical sources.','Light follows different paths through the curved spacetime around the foreground mass. Rays from one background source can reach the observer along more than one path and appear to arrive from different directions. The image geometry depends on the source, mass and observer alignment. This is lensing; light need not have nonzero invariant mass for its trajectory to be affected.']
];
function grScreens(){return GRcases.flatMap(([t,q,a])=>[S('Worked explanation · '+t,'<h2>'+esc(t)+'</h2>'+p(q)+'<textarea class="pf-response" aria-label="Predict the explanation"></textarea>','worked'),S('Worked explanation · reasoning for '+t,'<h2>Follow the causal explanation</h2>'+p(q)+p(a)+'<p>Each sentence connects an observable result to a physical mechanism. Keep the conditions in the final sentence when applying the idea to another situation.</p>','worked')]);}
function similarity(a,b){const stop=new Set(['with','from','that','this','have','into','about','force','energy','motion','worked','example','physics']);const words=new Set((a.toLowerCase().match(/[a-z]{4,}/g)||[]).filter(w=>!stop.has(w)));return (b.toLowerCase().match(/[a-z]{4,}/g)||[]).reduce((n,w)=>n+(words.has(w)?1:0),0);}
function deepen(id,mod,parentId,part){const parent=window.PhysicsFocused.parents[parentId]?.parent||mod;const g=G[id]||G[parentId];if(!g)throw Error('Missing explicit guide '+id);
 const original=mod.screens.slice();const foundation=foundations(id,mod,parentId,part);
 const seen=new Set();let count=0;
 const core=original.flatMap(s=>{if(s.type==='worked'||(extraGuides[id]&&s.type==='practice'&&s.html.includes('pf-model'))){seen.add(s.html.replace(/<span class="pf-phase[^]*?<\/span>/,''));const split=workedScreens(s,g,'Worked example '+(++count));if(split.length)return split;}return [s]});
 const supporting=[];const sourceWorks=parent.screens.filter(s=>s.type==='worked').sort((a,b)=>similarity(mod.title+' '+(mod.theory||''),b.title+' '+b.html.replace(/<[^>]+>/g,' '))-similarity(mod.title+' '+(mod.theory||''),a.title+' '+a.html.replace(/<[^>]+>/g,' ')));
 // Give each focused lesson at least two complete modelled examples where quantitative examples exist.
 for(const s of sourceWorks){if(count>=2)break;const normalized=s.html.replace(/<span class="pf-phase[^]*?<\/span>/,'');if(seen.has(normalized)||original.some(o=>o.html.endsWith(s.html)))continue;const split=workedScreens(s,g,'Background worked example '+(++count));if(split.length){supporting.push(...split);seen.add(normalized)}}
 if(parentId==='general-relativity')supporting.push(...grScreens());
 const independentAt=core.findIndex(s=>/^You · independent/.test(s.title));const at=independentAt<0?core.length:independentAt;
 let screens=[...core.slice(0,Math.min(2,at)),...foundation,...core.slice(Math.min(2,at),at),...supporting,...core.slice(at)];
 if(screens.length<30){
  const candidates=parent.screens.filter(s=>!['worked','review'].includes(s.type)&&!/^Do Now|Welcome|Learning aims|Review|Exit|Common|Mastery/.test(s.title)&&!original.some(o=>o.html.endsWith(s.html))).sort((a,b)=>similarity(mod.title+' '+(mod.theory||''),b.title+' '+b.html.replace(/<[^>]+>/g,' '))-similarity(mod.title+' '+(mod.theory||''),a.title+' '+a.html.replace(/<[^>]+>/g,' ')));
  for(const s of candidates){if(screens.length>=30)break;screens.splice(Math.min(2+foundation.length,screens.length),0,{...s,title:'Background · '+s.title})}
 }
 if(screens.length<30){const insert=caseStudies(g);screens.splice(Math.max(0,screens.length-2),0,...insert)}
 if(screens.length<30)throw Error('Insufficient substantive Physics content for '+id+': '+screens.length);
 mod.screens=screens;mod.explicitVersion='2026.10.12-explicit30';return screens.length;
}
// These source records are added below at build time; source identifiers are never guessed.
const EXAMS=window.PhysicsExplicitExamExamples||{};
function sourceExamScreens(record,g){
 const heading=record.sourcePublisher+' · '+record.examYear+' · Question '+record.sourceQuestionNumber;
 const source='<p class="pf-caption">'+esc(heading)+'. Historical paper: use only the concepts taught in this lesson. Explanatory notes are authored for Learning Vault WA; the original source question and suggested key remain identifiable.</p>';
 const answer=record.answer;const notes=(record.notes||[]).map((n,i)=>S('Past exam · explained step '+(i+1),'<h2>Reason through step '+(i+1)+'</h2>'+source+record.question+'<div class="pf-model">'+p(n)+'</div>','worked'));
 const block={title:heading,html:'<div class="worked-solution"><h2>'+esc(heading)+'</h2><p>Read the original question below.</p>'+record.question+answer+'</div>'};
 // Preserve complete question layouts and diagrams. Do not parse a multi-part source into missing subparts.
 return [S('Past exam · read and annotate','<h2>'+esc(heading)+'</h2>'+source+record.question+'<p>Annotate each requested quantity and write the relevant units before opening the method.</p>','practice'),...notes,S('Past exam · plan the solution','<h2>Choose the method before substituting</h2>'+source+record.question+formulaPanel(g)+p(g.diagram),'worked'),S('Past exam · working with explanations','<h2>Follow the working and explain each operation</h2>'+source+answer+g.relations.map(r=>p(r)+p(why(r,g))).join('')+p(g.limits),'worked')];
}
const audit=[];
for(const entry of window.PhysicsFocused.lessons){const mod=window['Year'+entry.year+'PhysicsLessons'][entry.id];const count=deepen(entry.id,mod,entry.parentTopic,entry.part);const exam=EXAMS[entry.id]||EXAMS[entry.parentTopic];if(exam){const examScreens=sourceExamScreens(exam,G[entry.id]||G[entry.parentTopic]);mod.screens.splice(mod.screens.length-2,0,...examScreens)}entry.subtitle='Explicit I–We–You · '+mod.screens.length+' slides · labelled diagrams · explained worked examples';for(const groups of Object.values(window.PhysicsFocused.sequences[entry.year]))for(const group of groups){const tile=group.lessons.find(t=>t.id===entry.id);if(tile)tile.subtitle=entry.subtitle}for(const s of mod.screens)s.html=s.html.replace(/Allow about 35–50 minutes, including written practice\./g,'Work at your own pace. Pause after each example; use more than one session if needed.').replace(/approximately 40–50 minutes\./g,'work at your own pace across one or more sessions.');audit.push({id:entry.id,year:entry.year,slides:mod.screens.length,worked:mod.screens.filter(s=>s.type==='worked').length,diagrams:mod.screens.filter(s=>/<svg|<img/.test(s.html)).length});}
for(const [id,info] of Object.entries(window.PhysicsFocused.parents)){const m=info.parent;deepen(id,m,id,1);const exam=EXAMS[id];if(exam)m.screens.splice(m.screens.length-2,0,...sourceExamScreens(exam,G[id]));info.topic.subtitle='Complete reference · '+m.screens.length+' slides · explicit worked examples';audit.push({id,year:info.year,slides:m.screens.length,worked:m.screens.filter(s=>s.type==='worked').length,diagrams:m.screens.filter(s=>/<svg|<img/.test(s.html)).length});}
window.PhysicsExplicitDepth={version:'2026.10.12-explicit30',audit};
